class Counter370 {
    var current: Int by Delegates.observable(98) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
sealed class Outcome371 {
    data class Success(val payload: String) : Outcome371()
    data object Failure : Outcome371()
}

fun describe371(outcome: Outcome371): String = when (outcome) {
    is Outcome371.Success -> outcome.payload
    Outcome371.Failure -> "failed"
}
fun <T> List<T>.secondOrNull372(): T? = if (size > 1) this[1] else null

fun render372(values: List<String>?): String {
    return values?.filter { it.isNotBlank() }?.joinToString(separator = ",") ?: "empty"
}
